//! Temperature and Tint on rendered (non-raw) pixels, as the Camera Raw Filter applies them.
//!
//! Measured as a black box on Photoshop 2026's Camera Raw Filter (Camera Raw 18.6) on a
//! 256-level grey ramp beside colour bands, at every 25 from −100 to 100; no Adobe code or data
//! was used. On a rendered image the sliders are not plain channel gains: each channel follows
//! its own curve of its level (−50 Temperature takes mid grey 128 to 102/146/211, lifting blue
//! most in the darks), and applying the grey ramp's three curves to each channel of a
//! photograph matches Photoshop to a mean ΔE76 of 1.2–1.6 at Tint ±50, 3.5–5.0 at Temperature
//! ±50 and 3–7 at ±100 on 17 photographs and renders (the earlier fixed gains: 10–60).
//! Temperature is applied first, then Tint; between measured values the curves interpolate.
//! The curves follow the greys; how coloured pixels move is a measured correction on top
//! ([`colour_lut`](super::colour_lut)), which brings the 17 images to a mean ΔE76 of 0.4–1.0.
//! Not reproduced: Photoshop leaves an image with no colour at all (every pixel grey) unchanged.

use super::Encoding;
use super::colour_lut::{Correction, Slider, correction};
use super::exposure::{STEPS, curve};
use crate::photo_util::par_rows;

static AT: [f32; 8] = [-100.0, -75.0, -50.0, -25.0, 25.0, 50.0, 75.0, 100.0];

/// The three channels' curves at slider value `v` (−100 … 100) over sRGB-encoded levels 0,
/// 1/64, …, 1, from `table` (identity at 0).
fn rows(table: &[[[f32; STEPS]; 3]; 8], v: f32) -> Option<[[f32; STEPS]; 3]> {
    if !v.is_finite() || v == 0.0 {
        return None;
    }
    let v = v.clamp(-100.0, 100.0);
    let id: [f32; STEPS] = std::array::from_fn(|k| k as f32 / (STEPS - 1) as f32);
    // Neighbouring measured values, with 0 the identity.
    let (lo, hi, f) = if v < 0.0 {
        let i = AT.iter().rposition(|a| *a <= v).unwrap_or(0);
        if i == 3 { (Some(i), None, (v - AT[3]) / (0.0 - AT[3])) } else { (Some(i), Some(i + 1), (v - AT[i]) / (AT[i + 1] - AT[i])) }
    } else {
        let i = AT.iter().position(|a| *a >= v).unwrap_or(7);
        if i == 4 { (None, Some(i), v / AT[4]) } else { (Some(i - 1), Some(i), (v - AT[i - 1]) / (AT[i] - AT[i - 1])) }
    };
    Some(std::array::from_fn(|c| {
        let a = lo.map_or(&id, |i| &table[i][c]);
        let b = hi.map_or(&id, |i| &table[i][c]);
        std::array::from_fn(|k| a[k] + (b[k] - a[k]) * f)
    }))
}

/// Temperature then Tint: each slider's per-channel curves and its measured correction.
#[derive(Clone, Debug, PartialEq)]
pub(crate) struct Balance(Vec<([[f32; STEPS]; 3], Option<Correction>)>);

/// Temperature and Tint (−100 … 100) as per-channel curves plus their corrections, `None` when
/// both are 0.
pub(crate) fn curves(temperature: f32, tint: f32) -> Option<Balance> {
    let v: Vec<_> = [(rows(&TEMPERATURE, temperature), Slider::Temperature, temperature), (rows(&TINT, tint), Slider::Tint, tint)]
        .into_iter()
        .filter_map(|(r, s, v)| r.map(|r| (r, correction(s, v))))
        .collect();
    (!v.is_empty()).then_some(Balance(v))
}

/// One straight pixel encoded with `enc` through the curves (each channel its own) and the
/// corrections.
pub(crate) fn pixel(mut q: [f32; 4], b: &Balance, enc: Encoding) -> [f32; 4] {
    for (rows, fix) in &b.0 {
        let out = stage([q[0], q[1], q[2]], rows, fix.as_ref(), enc);
        q[..3].copy_from_slice(&out);
    }
    q
}

/// One slider (Temperature or Tint) on a straight colour: its curves, then its correction.
fn stage(input: [f32; 3], rows: &[[f32; STEPS]; 3], fix: Option<&Correction>, enc: Encoding) -> [f32; 3] {
    let base: [f32; 3] = std::array::from_fn(|c| enc.encode(curve(&rows[c], enc.decode(input[c]))));
    fix.map_or(base, |f| f.apply(input, base, enc))
}

/// [`pixel`] stage by stage, `None` when Temperature or Tint pushes a channel that was below white
/// up to the clip: a near-white sample that clipping turns grey is not neutralised, and choosing
/// that setting would tint the rest of the image.
fn unclipped(mut q: [f32; 4], b: &Balance, enc: Encoding) -> Option<[f32; 4]> {
    const WHITE: f32 = 0.999;
    for (rows, fix) in &b.0 {
        let o = stage([q[0], q[1], q[2]], rows, fix.as_ref(), enc);
        if (0..3).any(|c| o[c] >= WHITE && q[c] < WHITE) {
            return None;
        }
        q[..3].copy_from_slice(&o);
    }
    Some(q)
}

/// Applies Temperature and Tint to straight RGBA pixels (`width` per row).
pub(crate) fn apply(px: &mut [[f32; 4]], width: usize, temperature: f32, tint: f32, enc: Encoding) {
    let Some(c) = curves(temperature, tint) else { return };
    par_rows(px, width, 1, |_, row| {
        for q in row.iter_mut() {
            *q = pixel(*q, &c, enc);
        }
    });
}

/// How far `c` (straight, encoded with `enc`) is from grey: squared log ratios of red and blue to
/// green in linear light. `None` for a colour too dark or not finite to judge.
fn cast(c: [f32; 3], enc: Encoding) -> Option<f32> {
    let lin = c.map(|v| enc.decode(v).max(1e-6));
    if lin.iter().any(|v| !v.is_finite()) || lin.iter().all(|v| *v < 1e-4) {
        return None;
    }
    let (r, b) = ((lin[0] / lin[1]).ln(), (lin[2] / lin[1]).ln());
    Some(r * r + b * b)
}

/// The White Balance eyedropper: the Temperature and Tint (−100 … 100, whole numbers as the
/// panel shows them) that turn `rgb` (a pixel of the image before Camera Raw, encoded as
/// `encoding_gamma` says, see [`CameraRaw::encoding_gamma`](super::CameraRaw)) grey, through the
/// same measured curves and corrections [`develop`](super::develop) applies. A grid search,
/// refined twice. `None` for a pixel too dark, clipped white or not finite, which has no colour
/// to read.
pub fn white_balance_from_sample(rgb: [f32; 3], encoding_gamma: f32) -> Option<(f32, f32)> {
    let enc = Encoding::of(encoding_gamma);
    if rgb.iter().any(|v| !v.is_finite()) || rgb.iter().all(|v| *v >= 0.999) {
        return None;
    }
    let q = [rgb[0], rgb[1], rgb[2], 1.0];
    let score = |t: f32, n: f32| -> Option<f32> {
        let o = match curves(t, n) {
            Some(b) => unclipped(q, &b, enc)?,
            None => q,
        };
        cast([o[0], o[1], o[2]], enc)
    };
    // The neutral setting is the one to beat: a candidate must read strictly greyer.
    let (mut best, mut at) = (score(0.0, 0.0)?, (0.0f32, 0.0f32));
    for (step, span) in [(10.0f32, 10i32), (2.0, 5), (0.5, 4)] {
        let centre = at;
        for i in -span..=span {
            for j in -span..=span {
                let (t, n) = ((centre.0 + i as f32 * step).clamp(-100.0, 100.0), (centre.1 + j as f32 * step).clamp(-100.0, 100.0));
                if let Some(s) = score(t, n).filter(|s| *s < best) {
                    (best, at) = (s, (t, n));
                }
            }
        }
    }
    Some((at.0.round(), at.1.round()))
}

/// Auto White Balance on rendered pixels (`px` straight, encoded as `encoding_gamma` says): the
/// eyedropper ([`white_balance_from_sample`]) on the image's mean neutral-ish colour, the mean of
/// its mid-tone pixels whose darkest channel is at least half the brightest (a grey-world estimate
/// that ignores strongly coloured areas, the clipped ends and fully transparent pixels). Not measured against Camera
/// Raw's own Auto, which is not documented. `(0, 0)` when nothing qualifies.
pub fn auto_white_balance(px: &[[f32; 4]], encoding_gamma: f32) -> (f32, f32) {
    let enc = Encoding::of(encoding_gamma);
    let (mut sum, mut n) = ([0.0f64; 3], 0usize);
    let step = (px.len() / 200_000).max(1);
    for q in px.iter().step_by(step).filter(|q| q[3] > 0.0) {
        let lin = [q[0], q[1], q[2]].map(|v| enc.decode(v));
        if lin.iter().any(|v| !v.is_finite()) {
            continue;
        }
        let (mx, mn) = (lin[0].max(lin[1]).max(lin[2]), lin[0].min(lin[1]).min(lin[2]));
        if mx < 0.02 || mx > 0.9 || mn < mx * 0.5 {
            continue;
        }
        for c in 0..3 {
            sum[c] += f64::from(lin[c]);
        }
        n += 1;
    }
    if n == 0 {
        return (0.0, 0.0);
    }
    let mean = sum.map(|v| enc.encode((v / n as f64) as f32));
    white_balance_from_sample(mean, encoding_gamma).unwrap_or((0.0, 0.0))
}

